          end
          3'b010: result_c = {63'b0, lt_imm_s};
          3'b011: result_c = {63'b0, (va < imm_i)};
          3'b100: result_c = va ^ imm_i;
          3'b101: begin
            case (funct7[6:1])
              6'b000000: result_c = va >> instr[25:20];
              6'b010000: result_c = sra64(va, instr[25:20]);
