        rf_we_c = 1'b1;
        wresult_c = 32'b0;
        case (funct3)
          3'b000: wresult_c = va[31:0] + imm_i[31:0];
          3'b001: begin
            if (funct7 != 7'b0) begin
              exception_c = 1'b1;
              exception_cause_c = 64'd2;
            end else begin
              wresult_c = va[31:0] << instr[24:20];
            end
          end
          3'b101: begin
            if (funct7 == 7'b0) begin
              wresult_c = va[31:0] >> instr[24:20];
            end else if (funct7 == 7'b0100000) begin
              wresult_c = sra32(va[31:0], instr[24:20]);
            end else begin
              exception_c = 1'b1;
              exception_cause_c = 64'd2;
            end
          end
          default: begin
            exception_c = 1'b1;
            exception_cause_c = 64'd2;
          end
        endcase
        result_c = wresult_sext;
      end
      7'b0110011: begin // OP
        rf_we_c = 1'b1;
        case ({funct7, funct3})
          10'b0000000000: result_c = va + vb;
          10'b0100000000: result_c = va - vb;
          10'b0000000001: result_c = va << vb[5:0];
          10'b0000000010: result_c =
            {63'b0, ((va[63] != vb[63]) ? va[63] : (va < vb))};
          10'b0000000011: result_c = {63'b0, (va < vb)};
          10'b0000000100: result_c = va ^ vb;
          10'b0000000101: result_c = va >> vb[5:0];
          10'b0100000101: result_c = sra64(va, vb[5:0]);
          10'b0000000110: result_c = va | vb;
          10'b0000000111: result_c = va & vb;
          10'b0000001000: begin // MUL
            rf_we_c = 1'b0; muldiv_start_c = 1'b1; muldiv_is_mul_c = 1'b1;
            muldiv_a_c = va; muldiv_b_c = vb;
          end
          10'b0000001001: begin // MULH
            rf_we_c = 1'b0; muldiv_start_c = 1'b1; muldiv_is_mul_c = 1'b1;
            muldiv_is_high_c = 1'b1;
            muldiv_a_c = va[63] ? (64'b0 - va) : va;
            muldiv_b_c = vb[63] ? (64'b0 - vb) : vb;
            muldiv_neg_product_c = va[63] ^ vb[63];
          end
          10'b0000001010: begin // MULHSU
            rf_we_c = 1'b0; muldiv_start_c = 1'b1; muldiv_is_mul_c = 1'b1;
            muldiv_is_high_c = 1'b1;
            muldiv_a_c = va[63] ? (64'b0 - va) : va;
            muldiv_b_c = vb;
            muldiv_neg_product_c = va[63];
          end
          10'b0000001011: begin // MULHU
            rf_we_c = 1'b0; muldiv_start_c = 1'b1; muldiv_is_mul_c = 1'b1;
            muldiv_is_high_c = 1'b1;
            muldiv_a_c = va; muldiv_b_c = vb;
          end
