          10'b0000001110: begin // REMW
            rf_we_c = 1'b0; muldiv_start_c = 1'b1; muldiv_is_word_c = 1'b1;
            muldiv_is_rem_c = 1'b1;
            muldiv_a_c = va_w[63] ? (64'b0 - va_w) : va_w;
            muldiv_b_c = vb_w[63] ? (64'b0 - vb_w) : vb_w;
