            result_c = csr_read_value(instr[31:20]);
          end else begin
            exception_c = 1'b1;
            exception_cause_c = 64'd2;
          end
        end
      end
      default: begin
        exception_c = 1'b1;
        exception_cause_c = 64'd2;
      end
    endcase
