                12'h003: csr_fcsr <= csr_wdata_c & 64'hff;
                12'h300: csr_mstatus <= csr_wdata_c;
                12'h304: csr_mie <= csr_wdata_c;
                12'h305: csr_mtvec <= csr_wdata_c;
                12'h340: csr_mscratch <= csr_wdata_c;
                12'h341: csr_mepc <= csr_wdata_c;
                12'h342: csr_mcause <= csr_wdata_c;
