              5'd20: x20 <= amo_old_value;
              5'd21: x21 <= amo_old_value;
              5'd22: x22 <= amo_old_value;
              5'd23: x23 <= amo_old_value;
              5'd24: x24 <= amo_old_value;
              5'd25: x25 <= amo_old_value;
              5'd26: x26 <= amo_old_value;
              5'd27: x27 <= amo_old_value;
              5'd28: x28 <= amo_old_value;
              5'd29: x29 <= amo_old_value;
              5'd30: x30 <= amo_old_value;
              5'd31: x31 <= amo_old_value;
            endcase
          end
          reservation_valid <= 1'b0;
          instret_count <= instret_count + 64'd1;
          pc <= pc + 64'd4;
          state <= S_FETCH;
        end
        default: state <= S_HALTED;
      endcase
